CREATE TABLE IF NOT EXISTS "ApiKey" (
 "id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"createdByMemberId" TEXT NOT NULL,"name" TEXT NOT NULL,"prefix" TEXT NOT NULL,"keyHash" TEXT NOT NULL,"scopes" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"status" TEXT NOT NULL DEFAULT 'active',"lastUsedAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ApiKey_pkey" PRIMARY KEY("id"),CONSTRAINT "ApiKey_workspaceId_fkey" FOREIGN KEY("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "ApiKey_createdByMemberId_fkey" FOREIGN KEY("createdByMemberId") REFERENCES "WorkspaceMember"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "ApiRequestLog" (
 "id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"apiKeyId" TEXT,"requestId" TEXT NOT NULL,"method" TEXT NOT NULL,"path" TEXT NOT NULL,"statusCode" INTEGER NOT NULL,"latencyMs" INTEGER NOT NULL,"errorCode" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ApiRequestLog_pkey" PRIMARY KEY("id"),CONSTRAINT "ApiRequestLog_workspaceId_fkey" FOREIGN KEY("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "ApiRequestLog_apiKeyId_fkey" FOREIGN KEY("apiKeyId") REFERENCES "ApiKey"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "WebhookEndpoint" (
 "id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"createdByMemberId" TEXT NOT NULL,"url" TEXT NOT NULL,"description" TEXT,"secretEncrypted" TEXT NOT NULL,"secretPrefix" TEXT NOT NULL,"events" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"status" TEXT NOT NULL DEFAULT 'active',"failureCount" INTEGER NOT NULL DEFAULT 0,"lastDeliveredAt" TIMESTAMP(3),"disabledAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "WebhookEndpoint_pkey" PRIMARY KEY("id"),CONSTRAINT "WebhookEndpoint_workspaceId_fkey" FOREIGN KEY("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "WebhookEndpoint_createdByMemberId_fkey" FOREIGN KEY("createdByMemberId") REFERENCES "WorkspaceMember"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS "WebhookDelivery" (
 "id" TEXT NOT NULL,"endpointId" TEXT NOT NULL,"eventId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"payload" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'queued',"attempts" INTEGER NOT NULL DEFAULT 0,"responseStatus" INTEGER,"nextAttemptAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"deliveredAt" TIMESTAMP(3),"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "WebhookDelivery_pkey" PRIMARY KEY("id"),CONSTRAINT "WebhookDelivery_endpointId_fkey" FOREIGN KEY("endpointId") REFERENCES "WebhookEndpoint"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS "ApiKey_prefix_key" ON "ApiKey"("prefix"); CREATE UNIQUE INDEX IF NOT EXISTS "ApiKey_keyHash_key" ON "ApiKey"("keyHash"); CREATE INDEX IF NOT EXISTS "ApiKey_workspaceId_status_idx" ON "ApiKey"("workspaceId","status"); CREATE INDEX IF NOT EXISTS "ApiKey_expiresAt_status_idx" ON "ApiKey"("expiresAt","status");
CREATE UNIQUE INDEX IF NOT EXISTS "ApiRequestLog_requestId_key" ON "ApiRequestLog"("requestId"); CREATE INDEX IF NOT EXISTS "ApiRequestLog_workspaceId_createdAt_idx" ON "ApiRequestLog"("workspaceId","createdAt"); CREATE INDEX IF NOT EXISTS "ApiRequestLog_apiKeyId_createdAt_idx" ON "ApiRequestLog"("apiKeyId","createdAt"); CREATE INDEX IF NOT EXISTS "ApiRequestLog_statusCode_createdAt_idx" ON "ApiRequestLog"("statusCode","createdAt");
CREATE INDEX IF NOT EXISTS "WebhookEndpoint_workspaceId_status_idx" ON "WebhookEndpoint"("workspaceId","status"); CREATE UNIQUE INDEX IF NOT EXISTS "WebhookDelivery_endpointId_eventId_key" ON "WebhookDelivery"("endpointId","eventId"); CREATE INDEX IF NOT EXISTS "WebhookDelivery_status_nextAttemptAt_idx" ON "WebhookDelivery"("status","nextAttemptAt"); CREATE INDEX IF NOT EXISTS "WebhookDelivery_endpointId_createdAt_idx" ON "WebhookDelivery"("endpointId","createdAt"); CREATE INDEX IF NOT EXISTS "WebhookDelivery_eventType_createdAt_idx" ON "WebhookDelivery"("eventType","createdAt");
